        File dir = new File(dirPath);
        if (!dir.exists() || !dir.isDirectory()) {
            throw new IllegalArgumentException("Directory does not exist or is not a directory: " + dirPath);
        }

        File[] files = dir.listFiles((d, name) -> name.toLowerCase().endsWith(".jar"));
        if (files == null) {
            return;
        }

        Vector<URL> urls = new Vector<>();
        for (File file : files) {
            urls.add(file.toURI().toURL());
        }

        URLClassLoader classLoader = new URLClassLoader(urls.toArray(new URL[0]), IntrospectionUtils.class.getClassLoader());
        // This approach works for Sun/Oracle JVMs but not all JVMs support adding URLs to system class loader
        // For broader compatibility, consider using reflection or alternative approaches
    }
}

