    public IsomorphicGraphMapping(Map<V, V> forwardMap, Map<V, V> backwardMap, Graph<V, E> sourceGraph, Graph<V, E> targetGraph) {
        this.forwardMap = forwardMap;
        this.backwardMap = backwardMap;
        this.sourceGraph = sourceGraph;
        this.targetGraph = targetGraph;
    }

    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        Map<V, V> fMap = new HashMap<>(graph.vertexSet().size());
        Map<V, V> bMap = new HashMap<>(graph.vertexSet().size());

        Set<V> vertices = graph.vertexSet();
        for (V v : vertices) {
            fMap.put(v, v);
            bMap.put(v, v);
        }

        return new IsomorphicGraphMapping<>(fMap, bMap, graph, graph);
    }
}

