public class StringSerializer {
    /**
     * Writes the utf8-encoded bytes from the string into the {@link LinkedBuffer}.
     */
    public LinkedBuffer writeUTF8(String str, LinkedBuffer buffer) {
        if (str == null) {
            throw new IllegalArgumentException("String must not be null");
        }

        int len = str.length();
        for (int i = 0; i < len; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                buffer.writeByte((byte) c);
            } else if (c < 0x800) {
                buffer.writeByte((byte) (0xC0 | (c >> 6)));
                buffer.writeByte((byte) (0x80 | (c & 0x3F)));
            } else {
                buffer.writeByte((byte) (0xE0 | (c >> 12)));
                buffer.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
                buffer.writeByte((byte) (0x80 | (c & 0x3F)));
            }
        }
        return buffer;
    }
}

