/**
 * Writes the utf8-encoded bytes from the string into the {@link LinkedBuffer}.
 */
public static LinkedBuffer writeUTF8(String str, LinkedBuffer buffer, int offset, int length, int session, int maxBufferLength, int maxStringSize, int flags) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }
    if (offset < 0 || length < 0 || offset + length > str.length()) {
        throw new IndexOutOfBoundsException();
    }

    int start = offset;
    int end = offset + length;

    // Write string length as vint
    int utf8Length = 0;
    for (int i = start; i < end; i++) {
        char ch = str.charAt(i);
        if (ch >= 0x0001 && ch <= 0x007F) {
            utf8Length++;
        } else if (ch <= 0x07FF) {
            utf8Length += 2;
        } else {
            utf8Length += 3;
        }
    }

    writeVInt(utf8Length, buffer, session, maxBufferLength, maxStringSize, flags);

    // Write UTF-8 encoded bytes
    for (int i = start; i < end; i++) {
        char ch = str.charAt(i);
        if (ch >= 0x0001 && ch <= 0x007F) {
            writeByte(ch, buffer, session, maxBufferLength, maxStringSize, flags);
        } else if (ch <= 0x07FF) {
            writeByte(0xC0 | (ch >> 6), buffer, session, maxBufferLength, maxStringSize, flags);
            writeByte(0x80 | (ch & 0x3F), buffer, session, maxBufferLength, maxStringSize, flags);
        } else {
            writeByte(0xE0 | (ch >> 12), buffer, session, maxBufferLength, maxStringSize, flags);
            writeByte(0x80 | ((ch >> 6) & 0x3F), buffer, session, maxBufferLength, maxStringSize, flags);
            writeByte(0x80 | (ch & 0x3F), buffer, session, maxBufferLength, maxStringSize, flags);
        }
    }

    return buffer;
}

private static void writeVInt(int value, LinkedBuffer buffer, int session, int maxBufferLength, int maxStringSize, int flags) {
    while ((value & ~0x7F) != 0) {
        writeByte((value & 0x7F) | 0x80, buffer, session, maxBufferLength, maxStringSize, flags);
        value >>>= 7;
    }
    writeByte(value, buffer, session, maxBufferLength, maxStringSize, flags);
}

private static void writeByte(int value, LinkedBuffer buffer, int session, int maxBufferLength, int maxStringSize, int flags) {
    if (buffer.next == null) {
        if (buffer.length >= buffer.buffer.length) {
            // Handle buffer overflow
            if (buffer.buffer.length >= maxBufferLength) {
                throw new BufferOverflowException();
            }
            int newCapacity = Math.min(buffer.buffer.length * 2, maxBufferLength);
            byte[] newBuffer = new byte[newCapacity];
            System.arraycopy(buffer.buffer, 0, newBuffer, 0, buffer.length);
            buffer.buffer = newBuffer;
        }
        buffer.buffer[buffer.length++] = (byte) value;
    } else {
        if (buffer.length >= buffer.buffer.length) {
            buffer = buffer.next;
            if (buffer == null) {
                throw new BufferOverflowException();
            }
        }
        buffer.buffer[buffer.length++] = (byte) value;
    }
}

class BufferOverflowException extends RuntimeException {
    public BufferOverflowException() {
        super("Buffer overflow");
    }
}

