 * Writes the utf8-encoded bytes from the string into the {@link LinkedBuffer}.
 */
public LinkedBuffer writeUTF8(String str, LinkedBuffer buffer, int offset, int length, boolean writeLength, int maxBytes, int maxChars, int flags, int encoding, int errorMode, int replacement, int flushMode) {
    if (str == null) {
        throw new NullPointerException("str");
    }

    int strLength = str.length();
    int maxLen = Math.min(strLength, maxChars);
    int start = offset;
    int end = start + maxLen;

    if (writeLength) {
        buffer = writeVInt(buffer, length);
    }

    int written = 0;
    for (int i = start; i < end && written < maxBytes; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            buffer = writeByte(buffer, (byte) ch);
            written++;
        } else if (ch < 0x800) {
            buffer = writeByte(buffer, (byte) (0xC0 | (ch >> 6)));
            buffer = writeByte(buffer, (byte) (0x80 | (ch & 0x3F)));
            written += 2;
        } else {
            buffer = writeByte(buffer, (byte) (0xE0 | (ch >> 12)));
            buffer = writeByte(buffer, (byte) (0x80 | ((ch >> 6) & 0x3F)));
            buffer = writeByte(buffer, (byte) (0x80 | (ch & 0x3F)));
            written += 3;
        }
    }

    return buffer;
}

