import java.net.URI;
import java.util.LinkedList;
import java.util.List;

public class UriComponent {
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        String rawPath = u.getRawPath();
        if (rawPath != null && rawPath.length() > 0 && rawPath.charAt(0) == '/') {
            rawPath = rawPath.substring(1);
        }
        return decodePath(rawPath, decode);
    }

    public static List<PathSegmentImpl> decodePath(String path, boolean decode) {
        List<PathSegmentImpl> segments = new LinkedList<>();
        if (path == null || path.isEmpty()) {
            return segments;
        }
        int s = 0;
        int e = -1;
        while (true) {
            e = path.indexOf('/', s);
            if (e == -1) {
                e = path.length();
            }
            if (e > s) {
                PathSegmentImpl segment = decodePathSegment(path.substring(s, e), decode);
                if (segment != null) {
                    segments.add(segment);
                }
            }
            if (e == path.length()) {
                break;
            }
            s = e + 1;
        }
        return segments;
    }

    private static PathSegmentImpl decodePathSegment(String segment, boolean decode) {
        if (segment == null || segment.isEmpty()) {
            return PathSegmentImpl.EMPTY_PATH_SEGMENT;
        }
        if (decode) {
            // Decode percent-encoded characters
            StringBuilder decoded = new StringBuilder(segment.length());
            for (int i = 0; i < segment.length(); i++) {
                char c = segment.charAt(i);
                if (c == '%' && i + 2 < segment.length()) {
                    try {
                        int hex = Integer.parseInt(segment.substring(i + 1, i + 3), 16);
                        decoded.append((char) hex);
                        i += 2;
                        continue;
                    } catch (NumberFormatException e) {
                        // Ignore malformed percent encoding
                    }
                }
                decoded.append(c);
            }
            return new PathSegmentImpl(decoded.toString());
        } else {
            return new PathSegmentImpl(segment);
        }
    }
}

class PathSegmentImpl {
    public static final PathSegmentImpl EMPTY_PATH_SEGMENT = new PathSegmentImpl("");

    private final String value;

    public PathSegmentImpl(String value) {
        this.value = value;
    }

    @Override
    public String toString() {
        return value;
    }
}

