import java.io.IOException;
import java.io.OutputStream;

public class Base64OutputStream extends OutputStream {
    private OutputStream out;
    private int[] buffer = new int[3];
    private int bufferLength = 0;

    public Base64OutputStream(OutputStream out) {
        this.out = out;
    }

    @Override
    public void write(int b) throws IOException {
        buffer[bufferLength++] = b;
        if (bufferLength == 3) {
            encodeBlock();
            bufferLength = 0;
        }
    }

    private void encodeBlock() throws IOException {
        int b1 = buffer[0];
        int b2 = buffer[1];
        int b3 = buffer[2];

        char c1 = (char) ((b1 >> 2) & 0x3F);
        char c2 = (char) (((b1 & 0x03) << 4) | ((b2 >> 4) & 0x0F));
        char c3 = (char) (((b2 & 0x0F) << 2) | ((b3 >> 6) & 0x03));
        char c4 = (char) (b3 & 0x3F);

        out.write(getBase64Char(c1));
        out.write(getBase64Char(c2));
        out.write(getBase64Char(c3));
        out.write(getBase64Char(c4));
    }

    private int getBase64Char(int index) {
        if (index < 26) return 'A' + index;
        if (index < 52) return 'a' + (index - 26);
        if (index < 62) return '0' + (index - 52);
        if (index == 62) return '+';
        return '/';
    }

    @Override
    public void close() throws IOException {
        if (bufferLength > 0) {
            for (int i = bufferLength; i < 3; i++) {
                buffer[i] = 0;
            }
            encodeBlock();
            for (int i = 0; i < (3 - bufferLength); i++) {
                out.write('=');
            }
        }
        out.close();
    }

    @Override
    public void flush() throws IOException {
        out.flush();
    }
}

