    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box)
    {
        double newWidth = box.getWidth() / 2d;
        double height = box.getHeight();
        return Pair.of(
            new Box2D(box.getMinX(), box.getMinY(), newWidth, height),
            new Box2D(box.getMinX() + newWidth, box.getMinY(), newWidth, height)
        );
    }
}

