public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int contentSize = 0, len;
        while (node != null) {
            len = node.end - node.start;
            out.write(node.buffer, node.start, len);
            contentSize += len;
            node = node.next;
        }
        return contentSize;
    }

