private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    content.put("msg_type", jsonObject.get("msg_type").getAsString());

    String ats = jsonObject.get("ats") == null ? "" : jsonObject.get("ats").getAsString();
    String text = jsonObject.get("content").getAsJsonObject().get("text").getAsString();

    if (!ats.isEmpty()) {
        List<String> atList = Arrays.stream(ats.split(","))
            .map(String::trim)
            .collect(Collectors.toList());
        content.put("ats", atList);
    }

    JsonObject contentObj = jsonObject.get("content").getAsJsonObject();
    contentObj.addProperty("text", text);
    content.put("content", contentObj);

    return content;
}

