protected int removeUnusedNodes() {
    int count = 0;
    CategoryNode root = _categoryModel.getRootCategoryNode();
    Enumeration<CategoryNode> enumeration = root.depthFirstEnumeration();
    while (enumeration.hasMoreElements()) {
        CategoryNode node = (CategoryNode) enumeration.nextElement();
        if (node.getNumberOfContainedRecords() == 0) {
            node.getParent().removeNodeFromParent(node);
            count++;
        }
    }
    return count;
}

