public final class UriPattern {
    private final Pattern regexPattern;
    private final String template;
    private static final MatchResult EMPTY_STRING_MATCH_RESULT = new MatchResult() {
        @Override
        public boolean matches() {
            return true;
        }

        @Override
        public String group(int i) {
            return "";
        }

        @Override
        public int groupCount() {
            return 0;
        }
    };

    public UriPattern(String template) {
        this.template = template;
        this.regexPattern = compileTemplateToPattern(template);
    }

    private static Pattern compileTemplateToPattern(String template) {
        if (template == null || template.isEmpty()) {
            return null;
        }
        String regex = template
            .replaceAll("\\{([^}]+)\\}", "([^/]+)")
            .replaceAll("\\*", ".*");
        return Pattern.compile("^" + regex + "$");
    }

    public final MatchResult match(CharSequence uri) {
        if (uri == null) {
            throw new IllegalArgumentException();
        }
        if (regexPattern == null) {
            return (template == null || template.isEmpty()) ? EMPTY_STRING_MATCH_RESULT : null;
        }
        Matcher m = regexPattern.matcher(uri);
        if (!m.matches()) {
            return null;
        }
        return (m.groupCount() > 0) ? new GroupIndexMatchResult(m) : m;
    }

    public final boolean match(CharSequence uri, List<String> groupValues) {
        if (uri == null) {
            throw new IllegalArgumentException();
        }
        if (regexPattern == null) {
            return template == null || template.isEmpty();
        }
        Matcher m = regexPattern.matcher(uri);
        if (!m.matches()) {
            return false;
        }
        groupValues.clear();
        int groupCount = m.groupCount();
        for (int i = 1; i <= groupCount; i++) {
            groupValues.add(m.group(i));
        }
        return true;
    }

    private static class GroupIndexMatchResult implements MatchResult {
        private final Matcher matcher;
        private final int[] groupIndexes;

        GroupIndexMatchResult(Matcher matcher) {
            this.matcher = matcher;
            this.groupIndexes = new int[matcher.groupCount()];
            for (int i = 0; i < groupIndexes.length; i++) {
                groupIndexes[i] = i + 1;
            }
        }

        @Override
        public boolean matches() {
            return matcher.matches();
        }

        @Override
        public String group(int i) {
            return matcher.group(groupIndexes[i - 1]);
        }

        @Override
        public int groupCount() {
            return groupIndexes.length;
        }
    }
}

