protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        List<V> vertices = new ArrayList<>(tour.size() + 1);
        tour.forEachRemaining(e -> {
            if (tour.contains(e)) {
                vertices.add(graph.getEdgeSource(e));
                vertices.add(graph.getEdgeTarget(e));
            }
        });
        return vertexListToTour(vertices, graph);
    }

answer_2:
protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<V> vertices = new ArrayList<>(tour.size() + 1);
    if (!tour.isEmpty()) {
        Iterator<E> it = tour.iterator();
        E firstEdge = it.next();
        vertices.add(graph.getEdgeSource(firstEdge));
        vertices.add(graph.getEdgeTarget(firstEdge));
        tour.forEachRemaining(e -> {
            if (!tour.contains(graph.getEdgeSource(e))) {
                vertices.add(graph.getEdgeSource(e));
            } else if (!tour.contains(graph.getEdgeTarget(e))) {
                vertices.add(graph.getEdgeTarget(e));
            }
        });
    }
    return vertexListToTour(vertices, graph);
}

