public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    int count = 0;
    int pos = 0;
    while ((pos = str.indexOf(sub, pos)) != -1) {
        count++;
        pos += sub.length();
    }
    return count;
}

