private void moveAllListNodes(DoublyLinkedList<E> list) {
    synchronized (this) {
        while (list.hasNext()) {
            Object node = list.nextNode();
            if (node == null) continue;
            ListNodeImpl<E> impl = (ListNodeImpl<E>) node;
            removeListNode(impl);
            addListNode(impl);
        }
    }
}

