        if (ch < 256) {
            return CHAR_ARRAY[ch];
        }
        return new Character(ch);
    }

    public static Character toCharacterObject(final String str) {
        if (str == null || str.isEmpty()) {
            return null;
        }
        return toCharacterObject(str.charAt(0));
    }
}

