public void abbreviate(final int nameStart, final StringBuffer buf) {
    int end = buf.length() - 1;
    String bufString = buf.toString();
    int lastDot = bufString.lastIndexOf(".", end - 1);
    if (lastDot >= nameStart) {
        buf.delete(nameStart, end + 1);
        buf.append(bufString.substring(lastDot + 1, end + 1));
        return;
    }
    int count = 0;
    for (int i = nameStart; i <= end; i++) {
        if (buf.charAt(i) == '.') {
            count++;
        }
    }
    if (count == 0) {
        return;
    }
    int pos = nameStart;
    for (int i = 0; i < count; i++) {
        int nextDot = buf.toString().indexOf(".", pos + 1);
        if (nextDot < 0) {
            break;
        }
        buf.delete(pos + 1, nextDot + 1);
        pos = nextDot;
    }
    int nextDot = buf.toString().indexOf(".", nameStart);
    if (nextDot < 0) {
        return;
    }
    int charCount = nextDot - nameStart;
    nextDot = abbreviate(buf, nameStart);
    while (nextDot >= 0) {
        nextDot = abbreviate(buf, nextDot);
    }
}

public int abbreviate(final StringBuffer buf, final int startPos) {
    int nextDot = buf.toString().indexOf(".", startPos);
    if (nextDot < 0) {
        return -1;
    }
    int charCount = nextDot - startPos;
    buf.delete(startPos + charCount, nextDot);
    buf.insert(nextDot, "...");
    return nextDot + 3;
}

