/**
 * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
 * @param path the path to start from (usually a full file path)
 * @param relativePath the relative path to apply(relative to the full file path above)
 * @return the full file path that results from applying the relative path
 */
public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        path = "";
    }
    if (relativePath == null) {
        relativePath = "";
    }

    // Normalize path separators
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Handle absolute path in relativePath
    if (relativePath.startsWith("/")) {
        return normalizePath(relativePath);
    }

    // Get directory part of path
    String basePath = path;
    int lastSlashIndex = path.lastIndexOf('/');
    if (lastSlashIndex >= 0) {
        basePath = path.substring(0, lastSlashIndex + 1);
    } else {
        basePath = "";
    }

    // Combine and normalize
    String combinedPath = basePath + relativePath;
    return normalizePath(combinedPath);
}

private static String normalizePath(String path) {
    if (path == null || path.isEmpty()) {
        return "";
    }

    // Remove duplicate slashes
    path = path.replaceAll("/+", "/");

    // Handle leading double slash
    if (path.startsWith("//") && !path.startsWith("///")) {
        path = "/" + path.substring(2);
    }

    // Process . and .. segments
    String[] segments = path.split("/");
    List<String> result = new ArrayList<>();

    for (String segment : segments) {
        if (segment.equals("..")) {
            if (!result.isEmpty() && !result.get(result.size() - 1).equals("..")) {
                result.remove(result.size() - 1);
            } else if (!path.startsWith("/")) {
                result.add(segment);
            }
        } else if (!segment.equals(".") && !segment.isEmpty()) {
            result.add(segment);
        }
    }

    StringBuilder normalized = new StringBuilder();
    if (path.startsWith("/") && !result.isEmpty()) {
        normalized.append("/");
    }

    for (int i = 0; i < result.size(); i++) {
        if (i > 0) {
            normalized.append("/");
        }
        normalized.append(result.get(i));
    }

    // Preserve trailing slash if original had one
    if (path.endsWith("/") && !normalized.toString().endsWith("/")) {
        normalized.append("/");
    }

    return normalized.toString();
}

