protected void append(LoggingEvent event) {
    if(layout.ignoresThrowable()) {
        String[] s = event.getThrowableStrRep();
        StringBuffer buf = new StringBuffer();
        for(int i = 0; i < s.length; i++) {
            buf.append(s[i]);
            buf.append("\n");
        }
        send(buf.toString());
    } else {
        send(layout.format(event));
    }
}

